/**
 * emit-sim-json — converts the SimDef .ts modules under components/sims_v2/
 * into runtime-fetched JSON under public/sims/.
 *
 * Why: the sims corpus is ~88MB of TypeScript that is almost entirely DATA
 * (giant object literals generated by tools/build_simdefs.mjs,
 * tools/wrap_masters.mjs and backend/its/competency/simdef_compiler.py).
 * Keeping it as TS forces webpack to parse/transform every byte at build
 * time — the module graph OOMs on normal dev machines. As JSON in public/,
 * sims are served statically and fetched one file at a time at play time.
 *
 * How: each .ts file is transpiled to CommonJS and executed with a stubbed
 * require() — every imported module resolves to tagged stand-in functions,
 * so `explore.component` refs survive serialization as `componentId` strings
 * resolved at runtime through engine/sim_components.gen.ts (next/dynamic).
 *
 * Defs that fail serialization (real function values, etc.) fall back to
 * residual_loaders.gen.ts — literal dynamic imports, one chunk per file.
 *
 * Outputs:
 *   public/sims/<cls>/<group>/<file>.json        { simId: SimDef }
 *   components/sims_v2/SIM_FILE_MAP.json         { simId: "<cls>/<group>/<file>" }
 *   components/sims_v2/engine/sim_components.gen.ts   componentId -> lazy component
 *   components/sims_v2/residual_loaders.gen.ts        simId -> dynamic import (fallback)
 *
 * Runs from `npm run prebuild` — re-run after regenerating sim sources.
 */
const fs = require('fs');
const path = require('path');
const ts = require('typescript');

const ROOT = path.join(__dirname, '..');
const V2 = path.join(ROOT, 'components', 'sims_v2');
const ENGINE = path.join(V2, 'engine');
const OUT = path.join(ROOT, 'public', 'sims');
const FILE_MAP_JSON = path.join(V2, 'SIM_FILE_MAP.json');
const REGISTRY_TS = path.join(ENGINE, 'sim_components.gen.ts');
const RESIDUAL_TS = path.join(V2, 'residual_loaders.gen.ts');

const SKIP_ROOT = new Set(['index.ts']);
const isRootDataFile = (f) =>
    f.endsWith('.ts') && !SKIP_ROOT.has(f) && !f.endsWith('_index.ts') &&
    !f.endsWith('_loaders.ts') && !f.startsWith('interactives');

/* ── transpile + execute a .ts module with all imports stubbed ─────────── */
function loadModule(file) {
    const src = fs.readFileSync(file, 'utf8');
    const js = ts.transpileModule(src, {
        compilerOptions: {
            module: ts.ModuleKind.CommonJS,
            target: ts.ScriptTarget.ES2020,
            esModuleInterop: true,
        },
        fileName: path.basename(file),
    }).outputText;
    const dir = path.dirname(file);
    const stubRequire = (spec) => new Proxy({}, {
        get: (t, prop) => {
            if (prop === '__esModule') return true;
            const name = prop === 'default' ? path.basename(spec) : String(prop);
            const fn = function () { };
            fn.__name = name;
            fn.__src = path.resolve(dir, spec);   // absolute path of the imported module
            return fn;
        },
    });
    const mod = { exports: {} };
    new Function('module', 'exports', 'require', js)(mod, mod.exports, stubRequire);
    return mod.exports;
}

/* ── collect SimDef-shaped exports from an executed module ─────────────── */
function defsOf(exportsObj) {
    const out = [];
    for (const v of Object.values(exportsObj)) {
        if (Array.isArray(v)) {
            for (const d of v) if (d && typeof d === 'object' && typeof d.id === 'string') out.push(d);
        } else if (v && typeof v === 'object' && typeof v.id === 'string') {
            out.push(v);
        }
    }
    return out;
}

/* ── serialize a def: functions -> component markers ────────────────────── */
const components = new Map();   // componentId -> absolute source path (no ext)

function sanitizeDef(def, file) {
    const json = JSON.stringify(def, (k, v) => {
        if (typeof v === 'function') {
            if (v.__name) return { __componentId: v.__name, __src: v.__src };
            throw new Error(`plain function value at "${k}"`);
        }
        return v;
    });
    const obj = JSON.parse(json);
    let leftover = 0;
    const walk = (o) => {
        if (!o || typeof o !== 'object') return;
        for (const k of Object.keys(o)) {
            const v = o[k];
            if (v && typeof v === 'object' && v.__componentId) {
                // component: <fn>  ->  componentId: '<name>'
                o[`${k}Id`] = v.__componentId;
                delete o[k];
                const prev = components.get(v.__componentId);
                const srcNoExt = v.__src.replace(/\.(tsx?|jsx?)$/, '');
                if (prev && prev !== srcNoExt) {
                    throw new Error(`component name collision: ${v.__componentId} (${prev} vs ${srcNoExt})`);
                }
                components.set(v.__componentId, srcNoExt);
            } else {
                walk(v);
            }
        }
    };
    walk(obj);
    // any marker still present means it sat somewhere other than a prop value
    JSON.stringify(obj, (k, v) => { if (v && v.__componentId) leftover++; return v; });
    if (leftover) throw new Error(`${leftover} component marker(s) in unsupported position`);
    return obj;
}

/* ── scan the corpus ────────────────────────────────────────────────────── */
function* scanFiles() {
    for (const cls of fs.readdirSync(V2)) {
        const clsDir = path.join(V2, cls);
        if (!/^class\d+$/.test(cls) || !fs.statSync(clsDir).isDirectory()) continue;
        for (const f of fs.readdirSync(clsDir)) {
            if (isRootDataFile(f)) yield { file: path.join(clsDir, f), group: 'cur', cls, base: f.replace(/\.ts$/, '') };
        }
        for (const sub of ['v3', 'v3w']) {
            const subDir = path.join(clsDir, sub);
            if (!fs.existsSync(subDir)) continue;
            for (const f of fs.readdirSync(subDir)) {
                if (f.endsWith('.ts') && !f.endsWith('_index.ts')) {
                    yield { file: path.join(subDir, f), group: sub, cls, base: f.replace(/\.ts$/, '') };
                }
            }
        }
    }
    const genDir = path.join(V2, 'generated');
    for (const f of fs.existsSync(genDir) ? fs.readdirSync(genDir) : []) {
        if (f.endsWith('_gen.ts')) yield { file: path.join(genDir, f), group: 'gen', cls: 'gen', base: f.replace(/\.ts$/, '') };
    }
}

/* ── main ───────────────────────────────────────────────────────────────── */
const fileMap = {};             // simId -> "<cls>/<group>/<base>"
const residual = new Map();     // simId -> absolute .ts path (no ext)
let emitted = 0, residualCount = 0, fileCount = 0;
const errors = [];

for (const { file, group, cls, base } of scanFiles()) {
    fileCount++;
    let defs;
    try {
        defs = defsOf(loadModule(file));
    } catch (e) {
        errors.push(`${path.relative(ROOT, file)}: execute failed — ${e.message}`);
        continue;
    }
    const pack = {};
    for (const def of defs) {
        try {
            pack[def.id] = sanitizeDef(def, file);
            fileMap[def.id] = `${cls}/${group}/${base}`;
        } catch (e) {
            residual.set(def.id, file.replace(/\.ts$/, ''));
            residualCount++;
            errors.push(`${path.relative(ROOT, file)}: def ${def.id} -> residual (${e.message})`);
        }
    }
    if (Object.keys(pack).length) {
        const outPath = path.join(OUT, cls, group, `${base}.json`);
        fs.mkdirSync(path.dirname(outPath), { recursive: true });
        fs.writeFileSync(outPath, JSON.stringify(pack));
        emitted += Object.keys(pack).length;
    }
}

fs.writeFileSync(FILE_MAP_JSON, JSON.stringify(fileMap, null, 0));

/* component registry — literal import() paths so webpack can chunk them */
const relFrom = (absNoExt) => {
    let r = path.relative(ENGINE, absNoExt).replace(/\\/g, '/');
    if (!r.startsWith('.')) r = './' + r;
    return r;
};
const regLines = [
    `/* GENERATED by scripts/emit-sim-json.js — do not edit.`,
    ` * componentId -> lazy component. Covers wrapped masters and the shared`,
    ` * interactives; every entry is its own webpack chunk. */`,
    `import dynamic from 'next/dynamic';`,
    `import type { ComponentType } from 'react';`,
    ``,
    `const pick = (load: () => Promise<Record<string, unknown>>, key: string) =>`,
    `    dynamic(() => load().then(m => (m[key] ?? m.default) as ComponentType));`,
    ``,
    `export const SIM_COMPONENTS: Record<string, ComponentType> = {`,
    ...[...components.entries()].sort().map(
        ([name, src]) => `    ${JSON.stringify(name)}: pick(() => import(${JSON.stringify(relFrom(src))}), ${JSON.stringify(name)}),`),
    `};`,
    ``,
];
fs.writeFileSync(REGISTRY_TS, regLines.join('\n'));

/* residual loaders — defs that could not be JSON'd keep their real modules */
const resByFile = new Map();
for (const [id, srcNoExt] of residual) {
    if (!resByFile.has(srcNoExt)) resByFile.set(srcNoExt, []);
    resByFile.get(srcNoExt).push(id);
}
const relFromV2 = (absNoExt) => {
    let r = path.relative(V2, absNoExt).replace(/\\/g, '/');
    if (!r.startsWith('.')) r = './' + r;
    return r;
};
const resLines = [
    `/* GENERATED by scripts/emit-sim-json.js — do not edit.`,
    ` * Defs that failed JSON serialization keep their real modules here. */`,
    `export const RESIDUAL_LOADERS: Record<string, () => Promise<Record<string, unknown>>> = {`,
    ...[...resByFile.entries()].sort().flatMap(([src, ids]) =>
        ids.sort().map(id => `    ${JSON.stringify(id)}: () => import(${JSON.stringify(relFromV2(src))}),`)),
    `};`,
    ``,
];
fs.writeFileSync(RESIDUAL_TS, resLines.join('\n'));

console.log(`emit-sim-json: ${fileCount} modules scanned, ${emitted} defs -> public/sims, ` +
    `${components.size} components, ${residualCount} residual defs`);
if (errors.length) {
    console.log(errors.slice(0, 40).join('\n'));
    if (errors.length > 40) console.log(`…and ${errors.length - 40} more`);
}
